package java.util.concurrent.atomic;
public class AtomicLong extends Number implements java.io.Serializable {
 private volatile long value; public AtomicLong(){} public AtomicLong(long initialValue){value=initialValue;} public final long get(){return value;} public final void set(long v){value=v;} public final void lazySet(long v){set(v);} public final synchronized long getAndSet(long v){long old=value;value=v;return old;} public final synchronized boolean compareAndSet(long expect,long update){if(value!=expect)return false;value=update;return true;} public final boolean weakCompareAndSet(long expect,long update){return compareAndSet(expect,update);} public final synchronized long getAndIncrement(){return value++;} public final synchronized long getAndDecrement(){return value--;} public final synchronized long getAndAdd(long d){long old=value;value+=d;return old;} public final synchronized long incrementAndGet(){return ++value;} public final synchronized long decrementAndGet(){return --value;} public final synchronized long addAndGet(long d){return value+=d;} public int intValue(){return (int)value;} public long longValue(){return (long)value;} public float floatValue(){return (float)value;} public double doubleValue(){return (double)value;} public String toString(){return String.valueOf(value);}  public final synchronized long getAndUpdate(java.util.function.LongUnaryOperator f){long old=value; value=f.applyAsLong(old); return old;} public final synchronized long updateAndGet(java.util.function.LongUnaryOperator f){return value=f.applyAsLong(value);} public final synchronized long getAndAccumulate(long x,java.util.function.LongBinaryOperator f){long old=value; value=f.applyAsLong(old,x); return old;} public final synchronized long accumulateAndGet(long x,java.util.function.LongBinaryOperator f){return value=f.applyAsLong(value,x);} }
